def _next_page(soup, current_url):
    link = soup.select_one("a[rel~='next'][href]")
    if link is None:
        for a in soup.find_all("a", href=True):
            label = _text(a).lower()
            aria = (a.get("aria-label") or "").lower()
            if label in ("next", "next page", "›", "»") or "next" in aria:
