    # The release page is a shell; its content comes from the JSON API, keyed by data-id.
    holder = soup.find(attrs={"data-id": True})
    rid = holder["data-id"] if holder is not None else known_id
    detail = {}
    if rid is not None and api_base:
        detail = _unwrap(_json_or_none(fetch(f"{api_base}/{quote(str(rid), safe='')}")))

    h1 = soup.find("h1")
    title = _clean_ws(detail.get("title") or (h1.get_text() if h1 else ""))

    # First publication date only; never "updated" or event dates.
