    seen = set()
    next_url = None
    for page in range(1, MAX_PAGES + 1):
        if next_url is None:
            if page > 1:
                params["page"] = str(page)
                params["offset"] = str(len(seen))
            url = f"{base}?{urlencode(params)}"
        else:
            url = next_url

        data = _json_or_none(fetch(url))
        items = data.get("items") if isinstance(data, dict) else data
        if not isinstance(items, list):
            return

        fresh = 0
        for item in items:
            if not isinstance(item, dict):
                continue
            key = item.get("slug") or item.get("id") or item.get("url")
            if key is None or key in seen:
                continue
            seen.add(key)
            fresh += 1
            yield item

        # Stop when a page adds nothing new, so an API that ignores paging cannot loop.
        if not fresh or _no_more(data):
            return
        next_url = _api_next(data, url)


