            found.update(t for t in re.split(r"[^a-z0-9]+", item.lower()) if t)
    return found


def _is_boilerplate(el):
    for node in [el, *el.parents]:
        if node.name in BOILERPLATE_TAGS:
            return True
        if _tokens(node.get("class"), node.get("id")) & BOILERPLATE_TOKENS:
            return True
