        if not rest or rest.startswith("fragments/") or re.search(r"(^|/)page/?\d+$", rest):
            continue
        if url in seen:
            continue
        seen.add(url)
        found.append((url, _listed_date(a)))
    return found


def _next_page(soup, current):
    link = soup.find("link", rel=lambda r: bool(r) and "next" in r)
