    raw = re.sub(r"\([^)]*\)", " ", raw)
    raw = re.sub(r"^\s*(written\s+|posted\s+)?by\s+", "", raw.strip(), flags=re.I)

    names = []
    for part in re.split(r"\s*(?:,|;|&|/|\|)\s*|\s+and\s+", raw, flags=re.I):
