    if link is None or not link.get("href"):
        return None
    nxt = urljoin(current, link["href"]).split("#")[0]
    return None if nxt == current else nxt


def _release(fetch, url, listed_date):
    soup = BeautifulSoup(fetch(url), "html.parser")
