    for match in DATE_RE.finditer(_fold(text or "")):
        month = MONTHS.get(match.group(2))
        if not month:
            continue
        try:
            return date(int(match.group(3)), month, int(match.group(1))).isoformat()
        except ValueError:
            continue
    return None


