        for a in soup.select(".pager a[href], a[rel~='next']"):
            nxt = urldefrag(urljoin(page_url, a["href"])).url
            parts = urlsplit(nxt)
            if parts.netloc == origin and parts.path == path and nxt not in seen_pages:
                queue.append(nxt)
    return entries


