import json
import re
from urllib.parse import urldefrag, urljoin, urlparse

from bs4 import BeautifulSoup
from bs4.element import NavigableString
from dateutil import parser as date_parser


MAX_LISTING_PAGES = 500

BLOCK_TAGS = ("h1", "h2", "h3", "h4", "h5", "h6", "p", "li", "dt", "dd", "td", "th",
              "blockquote", "pre", "figcaption", "table", "div", "section")
EXCLUDED_TAGS = {"nav", "aside", "footer", "header", "form", "button", "script",
                 "style", "noscript", "iframe", "svg", "select", "input", "textarea"}
EXCLUDED_CLASS_RE = re.compile(
    r"(?:^|[\s_-])(?:share|sharing|social|newsletter|subscribe|related|tags?|contact|"
    r"feedback|page-meta|meta|cookies?|breadcrumbs?|byline|about-us|boilerplate|"
    r"nav|menu|sidebar|promo|advert)(?=[\s_-]|$)",
    re.I,
)
NEXT_LABELS = {"next", "next page", "next »", "next ›", "older", "older posts",
               "older articles", "»", "›", ">"}


def _clean(text):
    return " ".join(str(text).split())


def _listing_links(soup, page_url, listing_url):
    root = urlparse(listing_url)
    prefix = root.path if root.path.endswith("/") else root.path + "/"
    scope = soup.find("main") or soup
    found = []
    for a in scope.find_all("a", href=True):
        absolute = urldefrag(urljoin(page_url, a["href"]))[0]
        link = urlparse(absolute)
        if link.scheme not in ("http", "https") or link.netloc.lower() != root.netloc.lower():
            continue
        if not link.path.startswith(prefix) or link.path.endswith("/"):
            continue
        if re.search(r"/page/\d+$", link.path) or re.search(r"(^|&)page=\d+", link.query):
            continue
        found.append(absolute)
    return found


def _next_page(soup, page_url):
    link = soup.select_one("link[rel~=next][href], a[rel~=next][href]")
    if link is None:
        for a in soup.find_all("a", href=True):
            label = _clean(a.get_text()).lower()
            aria = (a.get("aria-label") or "").lower()
            if label in NEXT_LABELS or "next" in aria:
                link = a
                break
    return urldefrag(urljoin(page_url, link["href"]))[0] if link is not None else None


def _news_json_ld(soup):
    for script in soup.find_all("script", type="application/ld+json"):
        try:
            data = json.loads(script.string or script.get_text() or "")
        except ValueError:
            continue
        for node in _ld_nodes(data):
            if _is_article(node):
                return node
    return None


def _ld_nodes(data):
    if isinstance(data, list):
        for item in data:
            yield from _ld_nodes(item)
    elif isinstance(data, dict):
        yield data
        if "@graph" in data:
            yield from _ld_nodes(data["@graph"])


def _is_article(node):
    types = node.get("@type")
    if isinstance(types, str):
        types = [types]
    if not isinstance(types, list):
        return False
    return any(isinstance(t, str) and "Article" in t for t in types)


def _title(soup, article, ld):
    h1 = article.find("h1") or soup.find("h1")
    if h1 is not None:
        text = _clean(h1.get_text())
        if text:
            return text
    if ld and isinstance(ld.get("headline"), str):
        return _clean(ld["headline"])
    og = soup.find("meta", property="og:title")
    if og and og.get("content"):
        return _clean(og["content"])
    if soup.title and soup.title.string:
        return _clean(soup.title.string.split(" | ")[0])
    return None


def _published_date(soup, ld):
    values = []
    if ld and isinstance(ld.get("datePublished"), str):
        values.append(ld["datePublished"])
    for selector in ('meta[property="article:published_time"]',
                     'meta[name="article:published_time"]',
                     'meta[itemprop="datePublished"]',
                     'meta[name="DC.date.issued"]',
                     'meta[name="date"]',
                     'time[itemprop="datePublished"]'):
        tag = soup.select_one(selector)
        if tag is not None:
            values.append(tag.get("content") or tag.get("datetime") or tag.get_text())
    for value in values:
        try:
            return date_parser.parse(str(value).strip()).date().isoformat()
        except (ValueError, OverflowError, TypeError):
            continue
    return None


def _ld_names(value):
    if isinstance(value, str):
        return [value]
    if isinstance(value, list):
        out = []
        for item in value:
            out.extend(_ld_names(item))
        return out
    if isinstance(value, dict):
        types = value.get("@type")
        types = [types] if isinstance(types, str) else (types or [])
        if types and "Person" not in types:
            return []
        name = value.get("name")
        return [name] if isinstance(name, str) else []
    return []


def _split_names(text):
    return [part for part in re.split(r";|&|\s+and\s+", _clean(text), flags=re.I) if part.strip()]


def _person_name(raw):
    text = _clean(raw)
    text = re.sub(r"^(?:written\s+)?by\s*:?\s+", "", text, flags=re.I)
    return text.split(",")[0].strip()


def _author(soup, article, ld):
    raw_names = []
    if ld:
        raw_names.extend(_ld_names(ld.get("author")))
    if not raw_names:
        meta = soup.select_one('meta[name="author"]')
        if meta is not None and meta.get("content"):
            raw_names.append(meta["content"])
    if not raw_names:
        byline = article.select_one('[rel~=author], [itemprop=author], .byline')
        if byline is not None:
            raw_names.append(byline.get_text(" "))
    names = []
    for raw in raw_names:
        for part in _split_names(raw):
            name = _person_name(part)
            if name and name not in names:
                names.append(name)
    return " and ".join(names) or None


def _content(article):
    return article.select_one(".prose") or article


def _excluded(tag):
    if tag.name in EXCLUDED_TAGS:
        return True
    classes = " ".join(tag.get("class") or [])
    ident = tag.get("id") or ""
    return bool(EXCLUDED_CLASS_RE.search(classes)) or bool(EXCLUDED_CLASS_RE.search(ident))


def _chain(el, container):
    chain = [el]
    for parent in el.parents:
        if parent is container:
            break
        chain.append(parent)
    return chain


def _own_text(el):
    parts = []
    for s in el.find_all(string=True):
        if type(s) is not NavigableString:
            continue
        blocked = False
        for parent in s.parents:
            if parent is el:
                break
            if parent.name in BLOCK_TAGS or _excluded(parent):
                blocked = True
                break
        if not blocked:
            parts.append(str(s))
    return _clean("".join(parts))


def _body(container, title):
    for br in container.find_all("br"):
        br.replace_with(" ")
    paragraphs = []
    for el in container.find_all(BLOCK_TAGS):
        if any(_excluded(node) for node in _chain(el, container)):
            continue
        text = _own_text(el)
        if text and text != title:
            paragraphs.append(text)
    return "\n\n".join(paragraphs)


def _parse_release(fetch, url):
    soup = BeautifulSoup(fetch(url), "html.parser")
    ld = _news_json_ld(soup)
    article = soup.find("article") or soup.find("main") or soup
    title = _title(soup, article, ld)
    return {
        "url": url,
        "title": title,
        "date": _published_date(soup, ld),
        "author": _author(soup, article, ld),
        "body": _body(_content(article), title),
    }


def extract(fetch, listing_url):
    listing_url = urldefrag(listing_url)[0]
    release_urls = []
    seen_urls = set()
    seen_pages = set()
    page_url = listing_url
    while page_url and page_url not in seen_pages and len(seen_pages) < MAX_LISTING_PAGES:
        seen_pages.add(page_url)
        soup = BeautifulSoup(fetch(page_url), "html.parser")
        for url in _listing_links(soup, page_url, listing_url):
            if url not in seen_urls:
                seen_urls.add(url)
                release_urls.append(url)
        page_url = _next_page(soup, page_url)

    records = [_parse_release(fetch, url) for url in release_urls]
    records.sort(key=lambda record: record["date"] or "", reverse=True)
    return records

import re
import xml.etree.ElementTree as ET
from datetime import date
from urllib.parse import parse_qs, urljoin, urlsplit

from bs4 import BeautifulSoup
from dateutil import parser as date_parser

RELEASE_PATH = re.compile(r"^/press/\d{4}/\d{2}/\d{2}/[^/]+/?$")
URL_DATE = re.compile(r"^/press/(\d{4})/(\d{2})/(\d{2})/")
PAGE_PATH = re.compile(r"/page/\d+/?$")
YEAR = re.compile(r"\b(?:19|20)\d{2}\b")
NOT_PUBLICATION_DATE = re.compile(
    r"updated|reviewed|revised|modified|effective|closing|closes|deadline|until|expires|event", re.I
)
ROLE_WORDS = re.compile(
    r"\b(director|analyst|head|senior|junior|associate|managing|chief|officer|partner|"
    r"manager|president|economist|lead|vice|principal|editor|chair)\b",
    re.I,
)
EXCLUDED_BLOCK = re.compile(r"share|newsletter|related|tags?|contact|cookie|disclaimer|social|advert|promo", re.I)
MAX_LISTING_PAGES = 200


def _clean(node):
    return " ".join(node.get_text(" ", strip=True).split())


def _absolute(base, href):
    parts = urlsplit(urljoin(base, href.strip()))
    return parts._replace(fragment="").geturl()


def _release_urls(soup, page_url, site):
    urls = []
    for a in soup.find_all("a", href=True):
        url = _absolute(page_url, a["href"])
        parts = urlsplit(url)
        if parts.netloc.lower() == site and RELEASE_PATH.match(parts.path):
            urls.append(parts._replace(query="").geturl())
    return urls


def _listing_pages(soup, page_url, listing_url):
    listing = urlsplit(listing_url)
    site = listing.netloc.lower()
    pages = []
    for a in soup.find_all("a", href=True):
        url = _absolute(page_url, a["href"])
        parts = urlsplit(url)
        if parts.netloc.lower() != site or not parts.path.startswith(listing.path):
            continue
        if RELEASE_PATH.match(parts.path):
            continue
        is_next = "next" in (a.get("rel") or [])
        if is_next or "page" in parse_qs(parts.query) or PAGE_PATH.search(parts.path):
            pages.append(url)
    return pages


def _feed_release_urls(soup, listing_url, fetch):
    # The listing itself is rendered by JavaScript, so the RSS feed advertised
    # in the page head is the reliable source of release links.
    link = soup.find("link", rel="alternate", type="application/rss+xml")
    if link is None or not link.get("href"):
        return []
    try:
        root = ET.fromstring(fetch(_absolute(listing_url, link["href"])).encode("utf-8"))
    except (FetchError, ET.ParseError):
        return []

    site = urlsplit(listing_url).netloc.lower()
    urls = []
    for node in root.iter():
        if node.tag.rsplit("}", 1)[-1] != "link":
            continue
        href = (node.get("href") or node.text or "").strip()
        if not href:
            continue
        parts = urlsplit(_absolute(listing_url, href))
        if parts.netloc.lower() == site and RELEASE_PATH.match(parts.path):
            urls.append(parts._replace(query="").geturl())
    return urls


def _parse_date(value):
    if not value or not YEAR.search(value):
        return None
    try:
        return date_parser.parse(value, fuzzy=True).date()
    except (ValueError, OverflowError):
        return None


def _publication_date(soup, url):
    candidates = []
    meta = soup.find("meta", attrs={"property": "article:published_time"})
    if meta is not None:
        candidates.append(meta.get("content"))
    time_tag = soup.find("time", attrs={"itemprop": "datePublished"})
    if time_tag is not None:
        candidates.append(time_tag.get("datetime") or _clean(time_tag))
    for span in soup.select(".pr-meta span"):
        label = _clean(span)
        if label and not NOT_PUBLICATION_DATE.search(label):
            candidates.append(label)
    for value in candidates:
        parsed = _parse_date(value)
        if parsed is not None:
            return parsed
    match = URL_DATE.match(urlsplit(url).path)
    return date(int(match.group(1)), int(match.group(2)), int(match.group(3)))


def _authors(soup):
    raw = None
    tag = soup.select_one(".pr-meta .analyst")
    if tag is not None:
        raw = _clean(tag)
    if not raw:
        meta = soup.find("meta", attrs={"name": "author"})
        raw = meta.get("content") if meta is not None else None
    if not raw:
        return None
    raw = re.sub(r"^(?:written\s+by|by|authors?|analysts?)\b\s*:?\s*", "", raw.strip(), flags=re.I)
    names = []
    for piece in re.split(r"\s*(?:,|;|&|\band\b)\s*", raw, flags=re.I):
        piece = piece.strip()
        if piece and not ROLE_WORDS.search(piece) and piece not in names:
            names.append(piece)
    return " and ".join(names) or None


def _inside_excluded(el, container):
    for parent in el.parents:
        if parent is container:
            break
        if EXCLUDED_BLOCK.search(" ".join(parent.get("class") or [])):
            return True
    return False


def _body(container):
    paragraphs = []
    for el in container.find_all(["p", "h2", "h3", "h4"]):
        if _inside_excluded(el, container):
            continue
        text = _clean(el)
        if text:
            paragraphs.append(text)
    return "\n\n".join(paragraphs)


def _parse_release(html, url):
    soup = BeautifulSoup(html, "html.parser")
    article = soup.find("article") or soup.find("main") or soup
    heading = article.find("h1")
    if heading is None:
        heading = soup.find("h1")
    title = _clean(heading) if heading is not None else ""
    container = article.select_one(".pr-body") or article
    return {
        "url": url,
        "title": title,
        "date": _publication_date(soup, url).isoformat(),
        "author": _authors(soup),
        "body": _body(container),
    }


def extract(fetch, listing_url):
    site = urlsplit(listing_url).netloc.lower()
    queue = [listing_url]
    visited = set()
    release_urls = []
    first_soup = None

    while queue and len(visited) < MAX_LISTING_PAGES:
        page_url = queue.pop(0)
        if page_url in visited:
            continue
        visited.add(page_url)
        soup = BeautifulSoup(fetch(page_url), "html.parser")
        if first_soup is None:
            first_soup = soup
        release_urls.extend(_release_urls(soup, page_url, site))
        queue.extend(_listing_pages(soup, page_url, listing_url))

    release_urls.extend(_feed_release_urls(first_soup, listing_url, fetch))

    seen = set()
    records = []
    for url in release_urls:
        key = url.rstrip("/")
        if key in seen:
            continue
        seen.add(key)
        records.append(_parse_release(fetch(url), url))

    records.sort(key=lambda record: record["date"], reverse=True)
    return records

