def _collect(node):
    out, buf = [], []
    _walk(node, out, buf)
    _flush(out, buf, "text")
    return out


def _walk(node, out, buf):
    for child in node.children:
        if isinstance(child, (Comment, Doctype)):
            continue
        if isinstance(child, NavigableString):
            buf.append(str(child))
        elif isinstance(child, Tag):
            if child.find(BLOCK_TAGS):
