                _walk(child, out, buf)
                _flush(out, buf, "text")
            elif child.name in BLOCK_TAGS:
                _flush(out, buf, "text")
                buf.append(child.get_text())
                _flush(out, buf, child.name)
            else:
                buf.append(child.get_text())


def _flush(out, buf, name):
    text = _clean_ws("".join(buf))
    del buf[:]
