    container = article.select_one(".post-content") or article
    for junk in container.select(_JUNK):
        junk.decompose()

    blocks = []
    for element in container.find_all(_BLOCK_TAGS):
        # Skip nested blocks; their text is already part of the outer block.
        if any(parent.name in _BLOCK_TAGS for parent in element.parents):
            continue
        text = _clean(element.get_text())
