    """Fetch a source and follow its 'next' links; add release URLs to found."""
    seen = set()
    queue = [start]
    got_any = False
    while queue and len(seen) < MAX_PAGES:
        u = queue.pop(0)
        if u in seen:
            continue
        seen.add(u)
