    for t in art.find_all('time'):
        ctx = _norm(t.parent.get_text(' ') if t.parent else '').lower()
        if re.search(r'updated|reviewed|modified', ctx) and not t.get('itemprop') == 'datePublished':
            continue
        d = _parse_date(t.get('datetime') or t.get_text())
