    s = _norm(s)
    if not s:
        return None
    m = re.search(r'\d{4}-\d{2}-\d{2}', s)
    if m and re.match(r'^\d{4}-\d{2}-\d{2}', s):
        return m.group(0)
    try:
        return dateparser.parse(s, fuzzy=True, dayfirst=False).strftime('%Y-%m-%d')
    except (ValueError, OverflowError, TypeError):
        return None


