    seen = set()

    def add(href):
        if not href:
            return
        u = _norm_url(urljoin(page_url, href))
        if u not in seen:
            seen.add(u)
            out.append(u)

    for a in soup.select("a.card-link[href]"):
        add(a["href"])
    if out:
        return out
    scope = soup.find("main") or soup
    base = listing_path.rstrip("/") + "/"
    for a in scope.find_all("a", href=True):
        u = urljoin(page_url, a["href"])
        p = urlparse(u)
        if p.path.startswith(base) and len(p.path) > len(base) and not p.query:
            add(u)
    return out


def _next_pages(soup, page_url, listing_path):
    found = []
    for el in soup.find_all(["a", "link"], href=True):
        rel = el.get("rel") or []
        if "next" in [r.lower() for r in rel]:
            found.append(el["href"])
    scope = soup.find("main") or soup
    for a in scope.find_all("a", href=True):
        txt = _clean(a.get_text()).lower()
        label = (a.get("aria-label") or "").lower()
        if txt in ("next", "next page", "next ›", "›", "»", "next »", "older") or "next" in label:
            found.append(a["href"])
        else:
            u = urlparse(urljoin(page_url, a["href"]))
            q = parse_qs(u.query)
            if u.path.rstrip("/") == listing_path.rstrip("/") and ("page" in q or "p" in q):
                found.append(a["href"])
    return [_norm_url(urljoin(page_url, h)) for h in found]


def _jsonld(soup):
    items = []
    for s in soup.find_all("script", type="application/ld+json"):
        try:
            data = json.loads(s.string or s.get_text())
        except Exception:
            continue
        stack = [data]
        while stack:
            d = stack.pop()
            if isinstance(d, list):
                stack.extend(d)
            elif isinstance(d, dict):
                items.append(d)
                if "@graph" in d:
                    stack.append(d["@graph"])
    return items


def _title(soup):
    h1 = soup.select_one("main h1.headline") or soup.select_one("h1.headline")
    if not h1:
        main = soup.find("main") or soup
        h1 = main.find("h1")
    if h1 and _clean(h1.get_text()):
        return _clean(h1.get_text())
    og = soup.find("meta", property="og:title")
    if og and og.get("content"):
        return _clean(og["content"])
    t = soup.find("title")
    if t:
        return _clean(re.sub(r"\s*\|[^|]*$", "", t.get_text()))
    return ""


def _date(soup):
    for d in _jsonld(soup):
        v = d.get("datePublished")
        if isinstance(v, str) and _parse_date(v):
            return _parse_date(v)
    for attrs in ({"property": "article:published_time"}, {"name": "article:published_time"},
                  {"itemprop": "datePublished"}, {"name": "date"}, {"name": "publish-date"},
                  {"property": "og:published_time"}):
        m = soup.find("meta", attrs=attrs)
        if m and m.get("content") and _parse_date(m["content"]):
            return _parse_date(m["content"])
    el = soup.find(attrs={"itemprop": "datePublished"})
    if el:
        d = _parse_date(el.get("datetime") or el.get("content") or el.get_text())
        if d:
            return d
    for el in soup.select(".dateline, .date, .publish-date, .published, .post-date"):
        txt = _clean(el.get_text())
        if re.search(r"updated|reviewed|modified", txt, re.I) and not re.search(r"published", txt, re.I):
            continue
        d = _parse_date(txt)
        if d:
            return d
    main = soup.find("main") or soup
    for t in main.find_all("time"):
        ctx = _clean(t.parent.get_text()) if t.parent else ""
        if re.search(r"updated|reviewed|modified", ctx, re.I):
            continue
        d = _parse_date(t.get("datetime") or t.get_text())
        if d:
            return d
    return None


def _split_names(text):
    text = _clean(text)
    text = re.sub(r"^\s*(written\s+)?by\s*:?\s*", "", text, flags=re.I)
    parts = re.split(r",|;|\s+and\s+|\s*&\s*", text)
    names = []
    for p in parts:
        p = _clean(p)
        if p and p not in names:
            names.append(p)
    return names


def _author(soup):
    scope = soup.find("main") or soup
    names = []
    for a in scope.select('[rel~="author"]'):
        n = _clean(a.get_text())
        if n and n not in names:
            names.append(n)
    if not names:
        for el in scope.select('[itemprop="author"], .authors, .author, .byline'):
            txt = _clean(el.get_text())
            if txt:
                for n in _split_names(txt):
                    if n not in names:
                        names.append(n)
                if names:
                    break
    if not names:
        for d in _jsonld(soup):
            a = d.get("author")
            for x in (a if isinstance(a, list) else [a]):
                n = x.get("name") if isinstance(x, dict) else x
                if isinstance(n, str) and _clean(n) and _clean(n) not in names:
                    names.append(_clean(n))
    names = [n for n in names if n.lower() not in ("northstar credit analytics", "staff", "admin")]
    return " and ".join(names) if names else None


def _body(soup):
    cont = (soup.select_one(".article-body") or soup.select_one('[itemprop="articleBody"]')
            or soup.select_one("article .body, article .content") or soup.find("article"))
    if cont is None:
        cont = soup.find("main") or soup
    for t in cont.find_all(["script", "style", "noscript", "form", "button", "nav", "aside"]):
        t.decompose()
    for el in list(cont.find_all(True)):
        if el.decomposed if hasattr(el, "decomposed") else False:
            continue
        cls = " ".join(el.get("class") or []) + " " + (el.get("id") or "")
        if cls.strip() and _NOISE_RE.search(cls) and el is not cont:
            el.decompose()
    for br in cont.find_all("br"):
        br.replace_with(" ")
    paras = []
    for el in cont.find_all(["p", "h2", "h3", "h4", "h5", "h6", "li"]):
        if el.find(["p", "li"]):
            continue
        txt = _clean(el.get_text())
        if not txt or _ABOUT_RE.match(txt):
            continue
        paras.append(txt)
    return "\n\n".join(paras)


def extract(fetch, listing_url):
    listing_path = urlparse(listing_url).path
    queue = [_norm_url(listing_url)]
    visited = set()
    urls = []
    seen_urls = set()
    while queue and len(visited) < MAX_PAGES:
        page = queue.pop(0)
        if page in visited:
            continue
        visited.add(page)
        try:
            html = fetch(page)
        except FetchError:
            if page == _norm_url(listing_url):
                raise
            continue
        soup = _soup(html)
        for u in _release_links(soup, page, listing_path):
            if u not in seen_urls and u not in visited:
                seen_urls.add(u)
                urls.append(u)
        for n in _next_pages(soup, page, listing_path):
            if n not in visited and n not in queue:
                queue.append(n)

    records = []
    for u in urls:
        try:
            html = fetch(u)
        except FetchError:
            continue
        soup = _soup(html)
        title = _title(soup)
        if not title:
            continue
        records.append({
            "url": u,
            "title": title,
            "date": _date(soup),
            "author": _author(soup),
            "body": _body(soup),
        })

    records.sort(key=lambda r: r["date"] or "", reverse=True)
    return records

import json
import re
from urllib.parse import urljoin, urlencode, urlparse, parse_qsl, urlunparse

from bs4 import BeautifulSoup, NavigableString, Tag
from dateutil import parser as dateparser

API_PATH = "/api/v2/news"
PAGE_LIMIT = 8
MAX_PAGES = 200

BLOCK_TAGS = {
    "p", "div", "section", "article", "ul", "ol", "li", "blockquote", "pre",
    "h1", "h2", "h3", "h4", "h5", "h6", "table", "tr", "figure", "figcaption",
    "dl", "dt", "dd", "header", "footer", "aside", "main",
}
DROP_TAGS = {"script", "style", "noscript", "form", "button", "iframe", "svg",
             "nav", "aside", "template"}
BOILER_RE = re.compile(
    r"share|social|related|newsletter|subscribe|cookie|breadcrumb|"
    r"(^|[-_ ])tags?([-_ ]|$)|contact|about-us|aboutus|boilerplate|"
    r"media-enquir|print|disclaimer|promo|signup|sign-up",
    re.I,
)
ABOUT_RE = re.compile(r"^\s*(about|über)\s+(harrow|us\b)", re.I)


def _loads(text):
    try:
        return json.loads(text)
    except (ValueError, TypeError):
        return None


def _plain(s):
    if s is None:
        return ""
    s = str(s)
    if "<" in s or "&" in s:
        s = BeautifulSoup(s, "html.parser").get_text(" ")
    return re.sub(r"\s+", " ", s).strip()


def _find_items(data):
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        for k in ("items", "results", "data", "news", "articles", "releases"):
            v = data.get(k)
            if isinstance(v, list):
                return v
            if isinstance(v, dict):
                r = _find_items(v)
                if r:
                    return r
    return []


def _get(d, *keys):
    for k in keys:
        if isinstance(d, dict) and d.get(k) not in (None, ""):
            return d[k]
    return None


def _next_link(data):
    if not isinstance(data, dict):
        return None
    cands = [data]
    for k in ("links", "pagination", "meta", "_links", "paging"):
        if isinstance(data.get(k), dict):
            cands.append(data[k])
    for c in cands:
        for k in ("next", "next_url", "nextUrl", "next_page_url", "next_link"):
            v = c.get(k)
            if isinstance(v, dict):
                v = v.get("href") or v.get("url")
            if isinstance(v, str) and v.strip():
                return v.strip()
    return None


def _more_expected(data, collected, page):
    if not isinstance(data, dict):
        return False
    cands = [data]
    for k in ("pagination", "meta", "paging", "links"):
        if isinstance(data.get(k), dict):
            cands.append(data[k])
    for c in cands:
        if c.get("has_more") is True or c.get("hasMore") is True or c.get("has_next") is True:
            return True
        total = _get(c, "total", "total_count", "totalItems", "count_total")
        if isinstance(total, int) and total > collected:
            return True
        tp = _get(c, "total_pages", "pages", "totalPages", "page_count")
        if isinstance(tp, int) and tp > page:
            return True
    return False


def _with_params(url, **params):
    p = urlparse(url)
    q = dict(parse_qsl(p.query))
    q.update({k: str(v) for k, v in params.items()})
    return urlunparse(p._replace(query=urlencode(q)))


def _item_key(it):
    return str(_get(it, "id", "slug", "url", "path", "uuid") or json.dumps(it, sort_keys=True))


def _list_items(fetch, listing_url):
    base = urljoin(listing_url, API_PATH)
    url = _with_params(base, limit=PAGE_LIMIT)
    seen, items = set(), []
    page = 1
    while url and page <= MAX_PAGES:
        try:
            data = _loads(fetch(url))
        except Exception:
            if page == 1:
                raise
            break
        got = _find_items(data)
        new = 0
        for it in got:
            if not isinstance(it, dict):
                continue
            k = _item_key(it)
            if k in seen:
                continue
            seen.add(k)
            items.append(it)
            new += 1
        if not got or not new:
            break
        nxt = _next_link(data)
        if nxt:
            url = urljoin(url, nxt)
        elif _more_expected(data, len(items), page) or len(got) >= PAGE_LIMIT:
            page += 1
            url = _with_params(base, limit=PAGE_LIMIT, page=page,
                               offset=len(items))
            if not _more_expected(data, len(items), page - 1) and len(got) < PAGE_LIMIT:
                break
            continue
        else:
            break
        page += 1
    return items


def _article_url(listing_url, it):
    u = _get(it, "url", "link", "permalink", "href")
    if isinstance(u, str) and "/api/" not in u:
        return urljoin(listing_url, u)
    slug = _get(it, "slug")
    if slug:
        return urljoin(listing_url, "/about/newsroom/article/%s" % slug)
    return None


# ---------- text extraction ----------

def _is_boiler(tag):
    if not isinstance(tag, Tag) or tag.attrs is None:
        return False
    ident = " ".join(
        [" ".join(tag.get("class") or []), tag.get("id") or "",
         tag.get("role") or "", tag.get("data-component") or ""]
    )
    return bool(ident.strip() and BOILER_RE.search(ident))


def _html_to_text(html):
    soup = BeautifulSoup(html or "", "html.parser")
    for t in list(soup.find_all(True)):
        if t.parent is None:
            continue
        if t.name in DROP_TAGS or _is_boiler(t):
            t.decompose()
    for br in soup.find_all("br"):
        br.replace_with("\n")

    paras = []
    buf = []

    def flush():
        txt = re.sub(r"[ \t\r\f\v\u00a0]+", " ", "".join(buf))
        txt = re.sub(r" ?\n ?", "\n", txt).strip()
        buf.clear()
        if txt:
            paras.append(txt)

    def walk(node):
        for ch in node.children:
            if isinstance(ch, NavigableString):
                if type(ch).__name__ in ("Comment", "Doctype", "CData"):
                    continue
                buf.append(str(ch).replace("\n", " ") if "\n" not in str(ch) else str(ch).replace("\n", " "))
            elif isinstance(ch, Tag):
                if ch.name in BLOCK_TAGS:
                    flush()
                    walk(ch)
                    flush()
                else:
                    walk(ch)

    walk(soup)
    flush()
    # trim trailing standard "About ..." boilerplate paragraphs
    out = []
    skipping = False
    for p in paras:
        if ABOUT_RE.match(p):
            skipping = True
        if skipping:
            continue
        out.append(p)
    return "\n\n".join(out)


# ---------- fields ----------

def _author(a):
    names = []

    def add(x):
        if x is None:
            return
        if isinstance(x, str):
            n = _plain(x)
        elif isinstance(x, dict):
            n = _plain(_get(x, "display_name", "name", "full_name", "fullName"))
            if not n:
                fn = _get(x, "first_name", "firstName")
                ln = _get(x, "last_name", "lastName")
                n = _plain("%s %s" % (fn or "", ln or ""))
        elif isinstance(x, list):
            for y in x:
                add(y)
            return
        else:
            return
        n = re.sub(r"^\s*by\s+", "", n, flags=re.I).strip()
        if n and n not in names:
            names.append(n)

    add(a)
    return " and ".join(names) if names else None


def _date(v):
    if v is None or v == "":
        return None
    try:
        if isinstance(v, (int, float)):
            from datetime import datetime, timezone
            if v > 1e11:
                v = v / 1000.0
            return datetime.fromtimestamp(v, timezone.utc).strftime("%Y-%m-%d")
        return dateparser.parse(str(v)).date().isoformat()
    except (ValueError, OverflowError, TypeError):
        return None


def _article_id(fetch, page_url):
    html = fetch(page_url)
    soup = BeautifulSoup(html, "html.parser")
    art = soup.find(attrs={"data-id": True})
    if art:
        return art["data-id"], soup
    m = re.search(r"/api/v\d+/news/([\w-]+)", html)
    return (m.group(1) if m else None), soup


def extract(fetch, listing_url):
    items = _list_items(fetch, listing_url)
    api_base = urljoin(listing_url, API_PATH)
    records = []
    for it in items:
        url = _article_url(listing_url, it)
        aid = None
        if url:
            try:
                aid, _ = _article_id(fetch, url)
            except Exception:
                aid = None
        if not aid:
            aid = _get(it, "id", "uuid")
        detail = None
        if aid is not None:
            try:
                detail = _loads(fetch("%s/%s" % (api_base, aid)))
            except Exception:
                detail = None
        if isinstance(detail, dict) and isinstance(detail.get("item"), dict):
            detail = detail["item"]
        elif isinstance(detail, dict) and isinstance(detail.get("data"), dict):
            detail = detail["data"]
        if not isinstance(detail, dict):
            continue
        if not url:
            slug = _get(detail, "slug")
            if not slug:
                continue
            url = urljoin(listing_url, "/about/newsroom/article/%s" % slug)
        title = _plain(_get(detail, "title", "headline")) or _plain(_get(it, "title", "headline"))
        date = _date(_get(detail, "published_at", "publishedAt", "publish_date",
                          "date_published", "first_published_at", "date")) \
            or _date(_get(it, "published_at", "publishedAt", "date"))
        body_html = _get(detail, "body_html", "body", "content_html", "content", "html")
        records.append({
            "url": url,
            "title": title,
            "date": date,
            "author": _author(detail.get("author", detail.get("authors", detail.get("byline")))),
            "body": _html_to_text(body_html if isinstance(body_html, str) else ""),
        })
    records.sort(key=lambda r: r["date"] or "", reverse=True)
    return records

import json
import re
