    if isinstance(data, dict):
        for k in ("items", "results", "data", "news", "articles", "releases"):
            v = data.get(k)
            if isinstance(v, list):
                return v
            if isinstance(v, dict):
                r = _find_items(v)
                if r:
                    return r
    return []


