def _g(d, *names):
    """Case/underscore-insensitive lookup of the first non-empty key."""
    if not isinstance(d, dict):
        return None
    m = {}
    for k, v in d.items():
        m.setdefault(_norm(k), v)
    for n in names:
        v = m.get(_norm(n))
        if v not in (None, "", [], {}):
