        items.extend(_listing_items(soup, page))
        for n in _next_pages(soup, page, listing_url):
            if n not in seen_pages and n not in queue:
                queue.append(n)

    records = []
    seen = set()
    for url, title, ldate in items:
        if url in seen:
            continue
        seen.add(url)
        try:
            html = fetch(url)
        except FetchError:
            continue
        rec = _extract_release(html, url, title, ldate)
        records.append(rec)

    order = {r["url"]: i for i, r in enumerate(records)}
    records.sort(key=lambda r: (r["date"] or "", -order[r["url"]]), reverse=True)
    return records

import re
from urllib.parse import urljoin, urlparse

from bs4 import BeautifulSoup
from dateutil import parser as dateparser

ITEM_RE = re.compile(r"news_item", re.I)
NEXT_TEXT_RE = re.compile(r"^\s*(next|older|older news|more news|more|next page|›|»|>|&gt;|\d+)\s*(›|»|>)?\s*$", re.I)
DATE_LABEL_RE = re.compile(r"^\s*(posted|published|publication date|date)(\s+on)?\s*:\s*(.+?)\s*$", re.I | re.S)
AUTHOR_LABEL_RE = re.compile(r"^\s*(posted by|written by|authors?|by)\s*:\s*(.+?)\s*$", re.I | re.S)
ORG_WORDS_RE = re.compile(r"\b(oakhill|group|team|office|department|press|communications|media|staff|editor)\b", re.I)
BOILERPLATE_RE = re.compile(
    r"^(about oakhill|about us|media contact|press contact|contact:|for more information|for further information|"
    r"share this|related (news|links)|tags?:|subscribe|sign up|newsletter|back to news|«\s*back)",
    re.I,
)


def _soup(html):
    return BeautifulSoup(html, "html.parser")


def _clean(text):
    return re.sub(r"\s+", " ", text.replace("\xa0", " ")).strip()


def _parse_date(text):
    text = _clean(text)
    try:
        return dateparser.parse(text, fuzzy=True, default=dateparser.parse("2000-01-01")).strftime("%Y-%m-%d")
    except (ValueError, OverflowError, TypeError):
        return None


def _listing_items(soup, base_url):
    items = []
    for a in soup.find_all("a", href=True):
        if ITEM_RE.search(a["href"]):
            url = urljoin(base_url, a["href"].strip())
            title = _clean(a.get_text(" "))
            container = a.find_parent("tr") or a.parent
            ctext = _clean(container.get_text(" ")) if container else ""
            items.append((url, title, _parse_date(ctext.replace(title, "")) if ctext else None))
    return items


def _next_pages(soup, base_url, listing_url):
    found = []
    lp = urlparse(listing_url)
    for a in soup.find_all("a", href=True):
        href = a["href"].strip()
        if not href or href.startswith(("#", "javascript:", "mailto:")) or ITEM_RE.search(href):
            continue
        rel = a.get("rel") or []
        text = _clean(a.get_text(" "))
        url = urljoin(base_url, href)
        p = urlparse(url)
        if p.netloc != lp.netloc:
            continue
        same_section = p.path == lp.path or p.path == urlparse(base_url).path
        if ("next" in [r.lower() for r in rel]) or (NEXT_TEXT_RE.match(text) and same_section and p.query):
            found.append(url)
        elif NEXT_TEXT_RE.match(text) and same_section and url != base_url:
            found.append(url)
    return found


def _extract_release(html, url, fallback_title, fallback_date):
    soup = _soup(html)
    for t in soup(["script", "style", "noscript"]):
        t.decompose()

    date = None
    author = None
    date_node = None
    author_node = None
    for s in soup.find_all(string=True):
        if date_node is None:
            m = DATE_LABEL_RE.match(s)
            if m:
                d = _parse_date(m.group(3))
                if d:
                    date, date_node = d, s
                    continue
        if author_node is None:
            m = AUTHOR_LABEL_RE.match(s)
            if m:
                author_node = s
                author = m.group(2)

    # content container
    anchor = date_node or author_node
    container = anchor.find_parent("td") if anchor else None
    if container is None:
        container = soup.find("body") or soup

    # title
    title = None
    for el in container.find_all(["h1", "h2", "font"]):
        if el.name == "font" and el.get("size") not in ("4", "5", "6"):
            continue
        txt = _clean(el.get_text(" "))
        if txt:
            title = txt
            title_el = el
            break
    if title is None:
        h = soup.find(["h1", "h2"])
        if h:
            title = _clean(h.get_text(" "))
            title_el = None
        else:
            title_el = None
            tt = soup.find("title")
            title = _clean(tt.get_text(" ")) if tt else fallback_title
            if " - " in title and fallback_title and title.endswith(fallback_title):
                title = fallback_title
    if title_el is not None and title_el.parent is not None:
        title_el.decompose()

    # author
    if author:
        author = _clean(author)
        parts = [p.strip() for p in re.split(r",|;|&|\band\b", author, flags=re.I) if p.strip()]
        names = []
        for p in parts:
            if ORG_WORDS_RE.search(p) or p.lower() in ("none", "n/a", "staff"):
                continue
            names.append(p)
        author = " and ".join(names) if names else None

    # strip metadata text nodes
    for node in (date_node, author_node):
        if node is not None:
            node.extract()
    if date is None:
        date = fallback_date

    # drop trailing navigation
    for a in container.find_all("a", href=True):
        if re.search(r"back to|«", a.get_text(), re.I):
            holder = a.find_parent("p") or a
            holder.decompose()

    for br in container.find_all("br"):
        br.replace_with("\n")
    for blk in container.find_all(["p", "div", "li", "h1", "h2", "h3", "h4", "ul", "ol", "table", "tr"]):
        blk.insert_before("\n\n")
        blk.insert_after("\n\n")

    text = container.get_text().replace("\xa0", " ")
    paras = []
    for line in re.split(r"\n+", text):
        line = _clean(line)
        if not line:
            continue
        if line == title:
            continue
        paras.append(line)

    # cut standard boilerplate and everything after it
    cleaned = []
    for p in paras:
        if BOILERPLATE_RE.match(p):
            break
        cleaned.append(p)
    body = "\n\n".join(cleaned)

    return {"url": url, "title": title, "date": date, "author": author, "body": body}


def extract(fetch, listing_url):
    items = []
    seen_pages = set()
    queue = [listing_url]
    while queue and len(seen_pages) < 50:
        page = queue.pop(0)
        if page in seen_pages:
            continue
        seen_pages.add(page)
        try:
            html = fetch(page)
        except FetchError:
            if page == listing_url:
                raise
            continue
        soup = _soup(html)
        items.extend(_listing_items(soup, page))
        for n in _next_pages(soup, page, listing_url):
            if n not in seen_pages and n not in queue:
                queue.append(n)

    records = []
    seen = set()
    for url, title, ldate in items:
        if url in seen:
            continue
        seen.add(url)
        try:
            html = fetch(url)
        except FetchError:
            continue
        rec = _extract_release(html, url, title, ldate)
        records.append(rec)

    order = {r["url"]: i for i, r in enumerate(records)}
    records.sort(key=lambda r: (r["date"] or "", -order[r["url"]]), reverse=True)
    return records

import json
import re
from urllib.parse import urljoin, urlparse, urldefrag

from bs4 import BeautifulSoup
from dateutil import parser as dateparser

DATE_RE = re.compile(
    r"\d{4}-\d{2}-\d{2}"
    r"|\d{1,2}(?:st|nd|rd|th)?\s+[A-Za-z]{3,9}\.?,?\s+\d{4}"
    r"|[A-Za-z]{3,9}\.?\s+\d{1,2}(?:st|nd|rd|th)?,?\s+\d{4}"
)
PUB_LABEL_RE = re.compile(
    r"^\s*(?:first\s+)?(published|posted|issued|released|release date|publication date|date published|date)\b\s*(?:on)?\s*[:\-–]?\s*(.*)$",
    re.I,
)
SKIP_DATE_RE = re.compile(r"updated|modified|reviewed|closes|closing|effective|event", re.I)
NOISE_CLASS_RE = re.compile(
    r"share|social|related|newsletter|subscribe|cookie|consent|breadcrumb|tags?\b|tag-|"
    r"contact|about|sidebar|promo|print|pagination|skip|banner|signup|sign-up|"
    r"keywords|topics|download|back-to|more-news|metadata|byline|author|published|"
    r"\blabel\b|dateline|release-date",
    re.I,
)
BLOCK_TAGS = ["p", "li", "h2", "h3", "h4", "h5", "h6", "blockquote", "pre"]


def _norm(s):
    return re.sub(r"\s+", " ", (s or "").replace("\xa0", " ")).strip()


def _parse_date(text):
    if not text:
        return None
    m = DATE_RE.search(text)
    if not m:
        return None
    frag = re.sub(r"(\d)(st|nd|rd|th)\b", r"\1", m.group(0))
    try:
        return dateparser.parse(frag, dayfirst=True).strftime("%Y-%m-%d")
    except (ValueError, OverflowError, TypeError):
        return None


def _is_release_label(text):
    return _norm(text).lower().rstrip(":") in ("news release", "news releases", "media release", "press release")


# ---------------------------------------------------------------- listing

def _listing_items(soup, page_url):
    items = []
    seen = set()
    root = soup.find("main") or soup
    for lab in root.find_all(True, class_=re.compile(r"label|tag|type|category|badge", re.I)):
        if not _is_release_label(lab.get_text()):
            continue
        container = lab.parent
        link = None
        for _ in range(4):
            if container is None:
                break
            link = container.find("a", href=True)
            if link:
                break
            container = container.parent
        if not link:
            continue
        url = urldefrag(urljoin(page_url, link["href"]))[0]
        if url in seen:
            continue
        seen.add(url)
        dt = None
        dnode = container.find(class_=re.compile(r"date|time", re.I))
        if dnode and not SKIP_DATE_RE.search(dnode.get_text()):
            dt = _parse_date(dnode.get_text())
        else:
            t = container.find("time")
            if t:
                dt = _parse_date(t.get("datetime", "") or t.get_text())
        items.append((url, dt))
    if not items:
        # fallback: no labels present, use URL path
        for a in root.find_all("a", href=True):
            url = urldefrag(urljoin(page_url, a["href"]))[0]
            path = urlparse(url).path
            if re.search(r"/news-release/[^/]+", path) and url not in seen:
                seen.add(url)
                items.append((url, None))
    return items


def _next_pages(soup, page_url, listing_url):
    out = []
    base_path = urlparse(listing_url).path.rstrip("/")
    for a in soup.find_all("a", href=True):
        txt = _norm(a.get_text()).lower()
        rel = a.get("rel") or []
        if isinstance(rel, str):
            rel = [rel]
        in_pager = False
        for p in a.parents:
            if p.name in ("nav", "ul", "div", "li") and p.get("class") or p.get("aria-label"):
                sig = " ".join(p.get("class", [])) + " " + (p.get("aria-label") or "")
                if re.search(r"pagin|pager|page-nav", sig, re.I):
                    in_pager = True
                    break
        is_next = "next" in rel or re.match(r"^(next|older|more)\b", txt) or txt in ("›", "»", ">", "→")
        is_num = in_pager and re.fullmatch(r"\d+", txt)
        if not (is_next or is_num or (in_pager and txt)):
            continue
        url = urldefrag(urljoin(page_url, a["href"]))[0]
        u = urlparse(url)
        if u.netloc != urlparse(listing_url).netloc:
            continue
        if not u.path.rstrip("/").startswith(base_path):
            continue
        if "/news-release/" in u.path:
            continue
        out.append(url)
    for link in soup.find_all("link", href=True):
        rel = link.get("rel") or []
        if "next" in rel:
            out.append(urldefrag(urljoin(page_url, link["href"]))[0])
    return out


# ---------------------------------------------------------------- release

def _find_title(soup):
    main = soup.find("main") or soup
    h1 = main.find("h1") or soup.find("h1")
    if h1:
        t = _norm(h1.get_text(" "))
        if t:
            return t
    og = soup.find("meta", property="og:title")
    if og and og.get("content"):
        return _norm(og["content"])
    if soup.title:
        return _norm(re.split(r"\s+[|\u2013\u2014-]\s+(?=[^|]*$)", soup.title.get_text())[0])
    return None


def _jsonld(soup):
    for s in soup.find_all("script", type=re.compile("ld\\+json", re.I)):
        try:
            data = json.loads(s.string or s.get_text())
        except ValueError:
            continue
        stack = [data]
        while stack:
            d = stack.pop()
            if isinstance(d, list):
                stack.extend(d)
            elif isinstance(d, dict):
                if "@graph" in d:
                    stack.append(d["@graph"])
                yield d


def _find_date(soup):
    main = soup.find("main") or soup
    for el in main.find_all(True):
        if el.name in ("script", "style") or el.find(["p", "div", "ul"]):
            continue
        txt = _norm(el.get_text(" "))
        if not txt or len(txt) > 80:
            continue
        m = PUB_LABEL_RE.match(txt)
        if m and not SKIP_DATE_RE.search(txt.split(":")[0]):
            d = _parse_date(m.group(2))
            if d:
                return d
    for el in main.find_all(class_=re.compile(r"publish|posted|release-date|dateline", re.I)):
        txt = _norm(el.get_text(" "))
        if len(txt) < 80 and not SKIP_DATE_RE.search(txt):
            d = _parse_date(txt)
            if d:
                return d
    for d in _jsonld(soup):
        v = d.get("datePublished")
        if isinstance(v, str) and _parse_date(v):
            return _parse_date(v)
    for key in ("article:published_time", "datePublished", "og:published_time"):
        m = soup.find("meta", attrs={"property": key}) or soup.find("meta", attrs={"name": key}) \
            or soup.find("meta", attrs={"itemprop": key})
        if m and m.get("content") and _parse_date(m["content"]):
            return _parse_date(m["content"])
    t = main.find("time", attrs={"datetime": True})
    if t and not SKIP_DATE_RE.search(_norm(t.parent.get_text(" ")) if t.parent else ""):
        d = _parse_date(t["datetime"])
        if d:
            return d
    return None


TITLE_WORDS = re.compile(
    r"\b(chief|director|manager|head|officer|chair|chairman|chairperson|president|spokes\w*|"
    r"commissioner|secretary|executive|editor|analyst|adviser|advisor|press|media|communications)\b",
    re.I,
)


def _clean_names(text):
    text = _norm(text)
    text = re.sub(r"^\s*(written\s+)?by\b\s*:?\s*", "", text, flags=re.I)
    text = re.sub(r"\s*[|•·]\s*.*$", "", text)
    names = []
    for part in re.split(r"\s+and\s+|\s*&\s*|;|\s*,\s*", text):
        part = _norm(part)
        part = re.sub(r"\s+[–—-]\s+.*$", "", part)
        if not part or TITLE_WORDS.search(part) or DATE_RE.search(part):
            continue
        if len(part) > 60:
            continue
        names.append(part)
    return names


def _find_author(soup):
    main = soup.find("main") or soup
    cands = []
    for el in main.find_all(True, attrs={"itemprop": "author"}):
        cands.append(el)
    for el in main.find_all(True, class_=re.compile(r"author|byline", re.I)):
        cands.append(el)
    for el in main.find_all("a", rel=True):
        if "author" in (el.get("rel") or []):
            cands.append(el)
    for el in cands:
        # prefer inner name element
        inner = el.find(True, class_=re.compile(r"name", re.I)) or el.find(attrs={"itemprop": "name"})
        txt = _norm((inner or el).get_text(" "))
        names = _clean_names(txt)
        if names:
            return " and ".join(dict.fromkeys(names))
    for el in main.find_all(["p", "div", "span"]):
        if el.find(["p", "div"]):
            continue
        txt = _norm(el.get_text(" "))
        if re.match(r"^by\s+[A-Z]", txt) and len(txt) < 120:
            names = _clean_names(txt)
            if names:
                return " and ".join(dict.fromkeys(names))
    for d in _jsonld(soup):
        a = d.get("author")
        if isinstance(a, dict):
            a = [a]
        if isinstance(a, list):
            nm = []
            for x in a:
                if isinstance(x, dict) and x.get("@type") in (None, "Person") and x.get("name"):
                    nm.extend(_clean_names(x["name"]))
            if nm:
                return " and ".join(dict.fromkeys(nm))
    return None


def _find_body(soup, title):
    main = soup.find("main") or soup.find("article") or soup.body or soup
    container = None
    for sel in (
        {"class_": re.compile(r"^(text|body|content|article-body|entry-content|release-body|rich-?text)$|release-text|article-text|post-content", re.I)},
    ):
        container = main.find(["div", "section", "article"], **sel)
    if container is None:
        container = main.find("article") or main
    container = BeautifulSoup(str(container), "html.parser")
    for t in container.find_all(["script", "style", "nav", "aside", "form", "footer", "header",
                                 "noscript", "button", "iframe", "svg", "select"]):
        t.decompose()
    for h in container.find_all("h1"):
        h.decompose()
    for t in container.find_all(True):
        if t.attrs is None:
            continue
        sig = " ".join(t.get("class", [])) + " " + (t.get("id") or "")
        if sig.strip() and NOISE_CLASS_RE.search(sig) and not re.fullmatch(r"\s*text\s*", sig):
            # do not delete the body wrapper itself
            if t.find_all(BLOCK_TAGS) and len(t.find_all("p")) > 3 and not re.search(r"share|related|about|contact|newsletter|cookie", sig, re.I):
                continue
            t.decompose()
    paras = []
    for el in container.find_all(BLOCK_TAGS):
        if el.find_parent(["blockquote", "li"]) and el.name != "li" and el.name != "blockquote":
            if el.find_parent(["blockquote", "li"]):
                continue
        if el.name == "li" and el.find_parent("li"):
            continue
        if el.name == "blockquote" and el.find(["p"]):
            continue
        txt = _norm(el.get_text(" "))
        txt = re.sub(r"\s+([,.;:!?])", r"\1", txt)
        if txt:
            paras.append((el.name, txt))
    out = []
    for name, txt in paras:
        if name in ("h2", "h3", "h4", "h5", "h6") and re.match(r"^(about|contact|media contact|related|share|notes to editors?|more information)\b", txt, re.I):
            break
        if re.match(r"^about the\b.{0,80}$", txt, re.I) and name != "p":
            break
        if re.match(r"^(share( this)?|related (links|news|articles)|tags?:|sign up|subscribe|media contact|for media (enquiries|inquiries))\b", txt, re.I):
            continue
        if txt == title:
            continue
        out.append(txt)
    return "\n\n".join(out)


def _parse_release(html, url, listing_date):
    soup = BeautifulSoup(html, "html.parser")
    title = _find_title(soup)
    if not title:
        return None
    date = _find_date(soup) or listing_date
    return {
        "url": url,
        "title": title,
        "date": date,
        "author": _find_author(soup),
        "body": _find_body(soup, title),
    }


# ---------------------------------------------------------------- entry

def extract(fetch, listing_url):
    items = []
    seen_items = set()
    seen_pages = set()
    queue = [listing_url]
    first = True
    while queue and len(seen_pages) < 200:
        page = queue.pop(0)
        key = page.rstrip("/")
        if key in seen_pages:
            continue
        seen_pages.add(key)
        try:
            html = fetch(page)
        except FetchError:
            if first:
                raise
            continue
        first = False
        soup = BeautifulSoup(html, "html.parser")
        for url, dt in _listing_items(soup, page):
            if url not in seen_items:
                seen_items.add(url)
                items.append((url, dt))
        for nxt in _next_pages(soup, page, listing_url):
            if nxt.rstrip("/") not in seen_pages:
                queue.append(nxt)

    records = []
    for url, ldate in items:
        try:
            html = fetch(url)
        except FetchError:
            continue
        rec = _parse_release(html, url, ldate)
        if rec:
            records.append(rec)

    indexed = list(enumerate(records))
    indexed.sort(key=lambda p: (p[1]["date"] or "", -p[0]), reverse=True)
    return [r for _, r in indexed]

