    seen_urls = set()
    first = True
    while queue and len(seen_pages) < 200:
        page = queue.pop(0)
        if page in seen_pages:
            continue
        seen_pages.add(page)
        try:
            html = fetch(page)
        except FetchError:
            if first:
                raise
            continue
        first = False
        soup = _soup(html)
        new = 0
        for u, a in _release_links(soup, page, listing_url):
            if u in seen_urls:
                continue
            seen_urls.add(u)
            new += 1
            entries.append((u, _listing_date(a)))
        for p in _pagination_links(soup, page, listing_url):
