def extract(fetch, listing_url):
    queue = [listing_url]
    seen_pages = set()
    found = {}
    order = []
    while queue and len(seen_pages) < 200:
        page = queue.pop(0)
        if page in seen_pages:
            continue
        seen_pages.add(page)
        try:
            html = fetch(page)
        except FetchError:
            if page == listing_url:
                raise
            continue
        items, pages = _listing_page(html, page, listing_url)
        for url, ldate in items:
            if url not in found:
                found[url] = ldate
                order.append(url)
        for p in pages:
            if p not in seen_pages and p not in queue:
                queue.append(p)

    records = []
    for idx, url in enumerate(order):
        try:
            html = fetch(url)
        except FetchError:
            continue
        rec = _parse_release(html, url)
        if not rec["date"]:
            rec["date"] = found[url]
        if not rec["title"]:
            continue
        records.append((rec, idx))
    records.sort(key=lambda r: (r[0]["date"] or "", -r[1]), reverse=True)
    return [r for r, _ in records]

