        if isinstance(o, list):
            for i in o:
                walk(i)
        elif isinstance(o, dict):
            objs.append(o)
            for v in o.get("@graph", []) if isinstance(o.get("@graph"), list) else []:
                walk(v)

    for s in soup.find_all("script", type=re.compile("ld\\+json", re.I)):
