        stack = [data]
        while stack:
            o = stack.pop()
            if isinstance(o, list):
                stack.extend(o)
            elif isinstance(o, dict):
                if 'datePublished' in o or 'headline' in o:
                    return o
                stack.extend(o.values())
    return {}


