                    t = _safe_fetch(fetch, _with_param(c, key, n))
                    if not t:
                        break
                    new = [x for x in _release_urls(t, c) if x not in found]
                    if not new:
                        break
                    for x in new:
                        found[x] = None
                    added_total += len(new)
                if added_total:
                    break
    # also plain page-number pagination on the listing, if it is static
    return list(found)


def _parse_date(s):
    s = _norm(s)
    if not s:
        return None
    m = re.search(r'\d{4}-\d{2}-\d{2}', s)
    if m and re.match(r'^\d{4}-\d{2}-\d{2}', s):
        return m.group(0)
    try:
        return dateparser.parse(s, fuzzy=True, dayfirst=False).strftime('%Y-%m-%d')
    except (ValueError, OverflowError, TypeError):
        return None


def _jsonld(soup):
    for sc in soup.find_all('script', type=re.compile('ld\\+json', re.I)):
        try:
            data = json.loads(sc.string or '')
        except ValueError:
            continue
        stack = [data]
        while stack:
            o = stack.pop()
            if isinstance(o, list):
                stack.extend(o)
            elif isinstance(o, dict):
                if 'datePublished' in o or 'headline' in o:
                    return o
                stack.extend(o.values())
    return {}


def _find_date(soup, url):
    ld = _jsonld(soup)
    if ld.get('datePublished'):
        d = _parse_date(str(ld['datePublished']))
        if d:
            return d
    for attrs in ({'property': 'article:published_time'}, {'name': 'date'},
                  {'itemprop': 'datePublished'}, {'name': 'publish-date'},
                  {'name': 'DC.date.issued'}):
        m = soup.find('meta', attrs=attrs)
        if m and m.get('content'):
            d = _parse_date(m['content'])
            if d:
                return d
    art = soup.find('article') or soup
    for t in art.find_all('time'):
        ctx = _norm(t.parent.get_text(' ') if t.parent else '').lower()
        if re.search(r'updated|reviewed|modified', ctx) and not t.get('itemprop') == 'datePublished':
            continue
        d = _parse_date(t.get('datetime') or t.get_text())
        if d:
            return d
    meta = art.find(class_=re.compile(r'pr-meta|meta|dateline|date', re.I))
    if meta:
        for span in meta.find_all(['span', 'time', 'div', 'p']) or [meta]:
            txt = _norm(span.get_text(' '))
            if re.search(r'updated|reviewed|modified|effective', txt, re.I):
                continue
            if re.search(r'\d{4}', txt) and re.search(r'[A-Za-z]{3,}|\d[/.-]\d', txt):
                d = _parse_date(re.sub(r'^(published|date)[:\s]+', '', txt, flags=re.I))
                if d:
                    return d
    m = URL_DATE_RE.search(url)
    if m:
        return '%s-%s-%s' % m.groups()
    return None


def _clean_names(raw):
    raw = _norm(raw)
    raw = re.sub(r'^(written\s+by|authored\s+by|author(s)?|by|analyst(s)?)\s*[:\-]?\s+', '', raw,
                 flags=re.I)
    names = []
    for part in re.split(r'\s+and\s+|\s*&\s*|;|\s*\|\s*', raw):
        part = re.split(r',|\s[-–—]\s', part)[0]
        part = re.sub(r'^(by|and)\s+', '', _norm(part), flags=re.I)
        if part and not re.search(r'meridian|ratings|staff|press office', part, re.I):
            names.append(part)
    return names


def _find_author(soup):
    ld = _jsonld(soup)
    a = ld.get('author')
    if a:
        items = a if isinstance(a, list) else [a]
        names = []
        for it in items:
            n = it.get('name') if isinstance(it, dict) else it
            if isinstance(n, str):
                names.extend(_clean_names(n))
        if names:
            return ' and '.join(names)
    art = soup.find('article') or soup
    el = art.find(class_=re.compile(r'analyst|author|byline', re.I)) or \
        art.find(attrs={'rel': 'author'}) or art.find(attrs={'itemprop': 'author'})
    if el:
        nested = el.find_all(class_=re.compile(r'author-name|name', re.I)) if \
            el.find(class_=re.compile(r'author-name|name', re.I)) else []
        if nested:
            names = []
            for n in nested:
                names.extend(_clean_names(n.get_text(' ')))
        else:
            names = _clean_names(el.get_text(' '))
        if names:
            return ' and '.join(dict.fromkeys(names))
        return None
    m = soup.find('meta', attrs={'name': 'author'})
    if m and m.get('content'):
        names = _clean_names(m['content'])
        if names:
            return ' and '.join(names)
    return None


def _find_title(soup):
    art = soup.find('article') or soup.find('main') or soup
    h = art.find('h1') or soup.find('h1')
    if h:
        t = _norm(h.get_text(' '))
        if t:
            return t
    m = soup.find('meta', attrs={'property': 'og:title'})
    if m and m.get('content'):
        return _norm(m['content'])
    if soup.title:
        return _norm(re.sub(r'\s*[|\-–]\s*Meridian Ratings\s*$', '', soup.title.get_text()))
    return ''


BLOCKS = ('p', 'h2', 'h3', 'h4', 'h5', 'h6', 'li', 'blockquote', 'pre')


def _find_body(soup):
    for t in soup(['script', 'style', 'noscript', 'nav', 'aside', 'form', 'button',
                   'iframe', 'header', 'footer']):
        t.decompose()
    container = None
    for sel in ('.pr-body', '[itemprop=articleBody]', '.article-body', '.release-body',
                '.press-body', '.entry-content', '.content-body'):
        container = soup.select_one(sel)
        if container:
            break
    if container is None:
        container = soup.find('article') or soup.find('main') or soup.body or soup
    for el in list(container.find_all(True)):
        if getattr(el, 'decomposed', False) or el.attrs is None:
            continue
        cls = ' '.join(el.get('class') or []) + ' ' + (el.get('id') or '')
        if el is not container and NOISE_CLASS_RE.search(cls):
            el.decompose()
    for br in container.find_all('br'):
        br.replace_with(' ')
    paras = []
    for el in container.find_all(BLOCKS):
        if any(p.name in BLOCKS for p in el.parents if p is not container
               and p in container.descendants):
            continue
        if el.name == 'h1':
            continue
        txt = _norm(el.get_text(''))
        if not txt:
            continue
        if re.match(r'^About\s+Meridian', txt, re.I):
            continue
        paras.append(txt)
    return '\n\n'.join(paras)


def _parse_release(html, url):
    soup = BeautifulSoup(html, 'html.parser')
    title = _find_title(soup)
    date = _find_date(soup, url)
    author = _find_author(soup)
    body = _find_body(soup)
    return {'url': url, 'title': title, 'date': date, 'author': author, 'body': body}


def extract(fetch, listing_url):
    urls = _discover(fetch, listing_url)
    records = []
    for u in urls:
        html = _safe_fetch(fetch, u)
        if not html:
            continue
        rec = _parse_release(html, u)
        if rec['title'] and rec['date']:
            records.append(rec)
    records.sort(key=lambda r: r['date'], reverse=True)
    return records

import json
import re
from urllib.parse import urljoin, urlparse, urldefrag, parse_qs

from bs4 import BeautifulSoup
from dateutil import parser as dateparser

MAX_PAGES = 200

_NOISE_RE = re.compile(
    r"share|social|newsletter|subscribe|related|tags?$|tag-|contact|about|cookie|"
    r"breadcrumb|analyst-box|promo|sidebar|byline|authors?$|dateline|disclaimer-nav",
    re.I,
)
_TITLES_RE = re.compile(
    r",.*$|\s+[-–|]\s+.*$|\((.*?)\)", re.S
)
_ABOUT_RE = re.compile(r"^\s*(about|über|acerca de)\s+(northstar|us)\b", re.I)


def _soup(html):
    try:
        return BeautifulSoup(html, "lxml")
    except Exception:
        return BeautifulSoup(html, "html.parser")


def _clean(text):
    return re.sub(r"\s+", " ", (text or "").replace("\xa0", " ")).strip()


def _norm_url(u):
    return urldefrag(u)[0]


def _parse_date(text):
    text = _clean(text)
    if not text:
        return None
    m = re.search(r"\d{4}-\d{2}-\d{2}", text)
    if m:
        return m.group(0)
    try:
        return dateparser.parse(text, fuzzy=True, default=dateparser.parse("2000-01-01")).strftime("%Y-%m-%d")
    except Exception:
        return None


def _release_links(soup, page_url, listing_path):
    out = []
    seen = set()

    def add(href):
        if not href:
            return
        u = _norm_url(urljoin(page_url, href))
        if u not in seen:
            seen.add(u)
            out.append(u)

    for a in soup.select("a.card-link[href]"):
        add(a["href"])
    if out:
        return out
    scope = soup.find("main") or soup
    base = listing_path.rstrip("/") + "/"
    for a in scope.find_all("a", href=True):
        u = urljoin(page_url, a["href"])
        p = urlparse(u)
        if p.path.startswith(base) and len(p.path) > len(base) and not p.query:
            add(u)
    return out


def _next_pages(soup, page_url, listing_path):
    found = []
    for el in soup.find_all(["a", "link"], href=True):
        rel = el.get("rel") or []
        if "next" in [r.lower() for r in rel]:
            found.append(el["href"])
    scope = soup.find("main") or soup
    for a in scope.find_all("a", href=True):
        txt = _clean(a.get_text()).lower()
        label = (a.get("aria-label") or "").lower()
        if txt in ("next", "next page", "next ›", "›", "»", "next »", "older") or "next" in label:
            found.append(a["href"])
        else:
            u = urlparse(urljoin(page_url, a["href"]))
            q = parse_qs(u.query)
            if u.path.rstrip("/") == listing_path.rstrip("/") and ("page" in q or "p" in q):
                found.append(a["href"])
    return [_norm_url(urljoin(page_url, h)) for h in found]


def _jsonld(soup):
    items = []
    for s in soup.find_all("script", type="application/ld+json"):
        try:
            data = json.loads(s.string or s.get_text())
        except Exception:
            continue
        stack = [data]
        while stack:
            d = stack.pop()
            if isinstance(d, list):
                stack.extend(d)
            elif isinstance(d, dict):
                items.append(d)
                if "@graph" in d:
                    stack.append(d["@graph"])
    return items


def _title(soup):
    h1 = soup.select_one("main h1.headline") or soup.select_one("h1.headline")
    if not h1:
        main = soup.find("main") or soup
        h1 = main.find("h1")
    if h1 and _clean(h1.get_text()):
        return _clean(h1.get_text())
    og = soup.find("meta", property="og:title")
    if og and og.get("content"):
        return _clean(og["content"])
    t = soup.find("title")
    if t:
        return _clean(re.sub(r"\s*\|[^|]*$", "", t.get_text()))
    return ""


def _date(soup):
    for d in _jsonld(soup):
        v = d.get("datePublished")
        if isinstance(v, str) and _parse_date(v):
            return _parse_date(v)
    for attrs in ({"property": "article:published_time"}, {"name": "article:published_time"},
                  {"itemprop": "datePublished"}, {"name": "date"}, {"name": "publish-date"},
                  {"property": "og:published_time"}):
        m = soup.find("meta", attrs=attrs)
        if m and m.get("content") and _parse_date(m["content"]):
            return _parse_date(m["content"])
    el = soup.find(attrs={"itemprop": "datePublished"})
    if el:
        d = _parse_date(el.get("datetime") or el.get("content") or el.get_text())
        if d:
            return d
    for el in soup.select(".dateline, .date, .publish-date, .published, .post-date"):
        txt = _clean(el.get_text())
        if re.search(r"updated|reviewed|modified", txt, re.I) and not re.search(r"published", txt, re.I):
            continue
        d = _parse_date(txt)
        if d:
            return d
    main = soup.find("main") or soup
    for t in main.find_all("time"):
        ctx = _clean(t.parent.get_text()) if t.parent else ""
        if re.search(r"updated|reviewed|modified", ctx, re.I):
            continue
        d = _parse_date(t.get("datetime") or t.get_text())
        if d:
            return d
    return None


def _split_names(text):
    text = _clean(text)
    text = re.sub(r"^\s*(written\s+)?by\s*:?\s*", "", text, flags=re.I)
    parts = re.split(r",|;|\s+and\s+|\s*&\s*", text)
    names = []
    for p in parts:
        p = _clean(p)
        if p and p not in names:
            names.append(p)
    return names


def _author(soup):
    scope = soup.find("main") or soup
    names = []
    for a in scope.select('[rel~="author"]'):
        n = _clean(a.get_text())
        if n and n not in names:
            names.append(n)
    if not names:
        for el in scope.select('[itemprop="author"], .authors, .author, .byline'):
            txt = _clean(el.get_text())
            if txt:
                for n in _split_names(txt):
                    if n not in names:
                        names.append(n)
                if names:
                    break
    if not names:
        for d in _jsonld(soup):
            a = d.get("author")
            for x in (a if isinstance(a, list) else [a]):
                n = x.get("name") if isinstance(x, dict) else x
                if isinstance(n, str) and _clean(n) and _clean(n) not in names:
                    names.append(_clean(n))
    names = [n for n in names if n.lower() not in ("northstar credit analytics", "staff", "admin")]
    return " and ".join(names) if names else None


def _body(soup):
    cont = (soup.select_one(".article-body") or soup.select_one('[itemprop="articleBody"]')
            or soup.select_one("article .body, article .content") or soup.find("article"))
    if cont is None:
        cont = soup.find("main") or soup
    for t in cont.find_all(["script", "style", "noscript", "form", "button", "nav", "aside"]):
        t.decompose()
    for el in list(cont.find_all(True)):
        if el.decomposed if hasattr(el, "decomposed") else False:
            continue
        cls = " ".join(el.get("class") or []) + " " + (el.get("id") or "")
        if cls.strip() and _NOISE_RE.search(cls) and el is not cont:
            el.decompose()
    for br in cont.find_all("br"):
        br.replace_with(" ")
    paras = []
    for el in cont.find_all(["p", "h2", "h3", "h4", "h5", "h6", "li"]):
        if el.find(["p", "li"]):
            continue
        txt = _clean(el.get_text())
        if not txt or _ABOUT_RE.match(txt):
            continue
        paras.append(txt)
    return "\n\n".join(paras)


def extract(fetch, listing_url):
    listing_path = urlparse(listing_url).path
    queue = [_norm_url(listing_url)]
    visited = set()
    urls = []
    seen_urls = set()
    while queue and len(visited) < MAX_PAGES:
        page = queue.pop(0)
        if page in visited:
            continue
        visited.add(page)
        try:
            html = fetch(page)
        except FetchError:
            if page == _norm_url(listing_url):
                raise
            continue
        soup = _soup(html)
        for u in _release_links(soup, page, listing_path):
            if u not in seen_urls and u not in visited:
                seen_urls.add(u)
                urls.append(u)
        for n in _next_pages(soup, page, listing_path):
            if n not in visited and n not in queue:
                queue.append(n)

    records = []
    for u in urls:
        try:
            html = fetch(u)
        except FetchError:
            continue
        soup = _soup(html)
        title = _title(soup)
        if not title:
            continue
        records.append({
            "url": u,
            "title": title,
            "date": _date(soup),
            "author": _author(soup),
            "body": _body(soup),
        })

    records.sort(key=lambda r: r["date"] or "", reverse=True)
    return records

