    if "<" in s or "&" in s:
        s = BeautifulSoup(s, "html.parser").get_text(" ")
    return re.sub(r"\s+", " ", s).strip()


def _g(d, *names):
    """Case/underscore-insensitive lookup of the first non-empty key."""
    if not isinstance(d, dict):
