    def walk(node):
        for ch in node.children:
            if isinstance(ch, NavigableString):
                if type(ch).__name__ in ("Comment", "Doctype", "CData"):
                    continue
                s = str(ch)
                buf.append(s)
            elif isinstance(ch, Tag):
                if ch.name in BLOCK_TAGS:
                    flush()
                    walk(ch)
                    flush()
                else:
