        for u in _release_links(soup, page, listing_url):
            if u not in urls and u.rstrip("/") != listing_url.rstrip("/"):
                urls.append(u)
        for n in _next_pages(soup, page):
            if n not in seen_pages:
                queue.append(n)
    return urls


