def _jsonld(soup):
    out = []
    for s in soup.find_all("script", type="application/ld+json"):
        try:
            data = json.loads(s.string or s.get_text())
        except Exception:
            continue
        stack = [data]
        while stack:
            d = stack.pop()
            if isinstance(d, list):
                stack.extend(d)
            elif isinstance(d, dict):
                out.append(d)
                stack.extend(v for v in d.values() if isinstance(v, (list, dict)))
    return out


def _parse_date(text):
    text = _ws(text)
    if not text:
        return None
    try:
        return dateparser.parse(text, dayfirst=True, fuzzy=True).strftime("%Y-%m-%d")
    except (ValueError, OverflowError, TypeError):
        return None


def _find_date(soup, root):
    for d in _jsonld(soup):
        v = d.get("datePublished")
        if isinstance(v, str) and _parse_date(v):
            return _parse_date(v)
    m = soup.find("meta", attrs={"property": "article:published_time"})
    if m and m.get("content") and _parse_date(m["content"]):
        return _parse_date(m["content"])
    skip = re.compile(r"updated|modified|reviewed|effective|closing|event", re.I)
    cands = root.select("[class*=date], time") if root else []
    for el in cands:
        ctx = " ".join(el.get("class", [])) + " " + (el.parent.get_text(" ") if False else "")
        prev = _ws(el.previous_sibling.get_text() if hasattr(el.previous_sibling, "get_text")
                   else (el.previous_sibling or ""))
        if skip.search(ctx) or skip.search(prev[-30:]):
            continue
        val = el.get("datetime") or el.get_text()
        d = _parse_date(val)
        if d:
            return d
    return None


def _clean_name(name):
    name = _ws(name)
    name = re.sub(r"^(written\s+)?by\s*:?\s+", "", name, flags=re.I)
    name = name.split(",")[0].split(" | ")[0].split(" - ")[0].split(" – ")[0]
    return _ws(name)


def _find_author(soup, root):
    names = []
    els = root.select("[class*=author], [rel=author], [itemprop=author]") if root else []
    for el in els:
        if el.find(attrs={"class": re.compile("author")}) and el.name not in ("a", "span"):
            pass
        t = _ws(el.get_text(" "))
        if t:
            for part in re.split(r"\s+and\s+|\s*&\s*|;|\s*/\s*", t):
                n = _clean_name(part)
                if n and n not in names:
                    names.append(n)
        if names:
            break
    if not names:
        for d in _jsonld(soup):
            a = d.get("author")
            for x in (a if isinstance(a, list) else [a]):
                n = x.get("name") if isinstance(x, dict) else x
                if isinstance(n, str) and _clean_name(n) and _clean_name(n) not in names:
                    names.append(_clean_name(n))
        m = soup.find("meta", attrs={"name": "author"})
        if not names and m and m.get("content"):
            names.append(_clean_name(m["content"]))
    names = [n for n in names if n]
    return " and ".join(names) if names else None


def _blocks(container):
    out = []
    for el in container.find_all(BLOCK_TAGS):
        if el.find(BLOCK_TAGS):
            continue
        for br in el.find_all("br"):
            br.replace_with(" ")
        t = _ws(el.get_text())
        if not t:
            continue
        if el.name in ("h2", "h3", "h4", "h5", "h6") and re.match(r"(about|contact|related|share|more from)\b", t, re.I):
            break
        out.append(t)
    if not out:
        for line in container.get_text("\n").split("\n"):
            line = _ws(line)
            if line:
                out.append(line)
    return out


def _parse_release(fetch, url):
    html = _get(fetch, url)
    if html is None:
        return None
    soup = _soup(html)
    root = soup.find("article") or soup.find("main") or soup.body or soup

    h1 = root.find("h1") or soup.find("h1")
    title = _ws(h1.get_text()) if h1 else None
    if not title:
        t = soup.find("title")
        title = _ws(t.get_text()).split(" | ")[0] if t else ""

    date = _find_date(soup, root)
    author = _find_author(soup, root)

    # Load lazily-injected fragments
    for el in root.find_all(attrs={"data-src": True}):
        frag = _get(fetch, urljoin(url, el["data-src"]))
        if frag is None:
            continue
        fs = _soup(frag)
        for b in el.find_all("button"):
            b.decompose()
        el.append(fs)

    for t in root.find_all(STRIP_TAGS):
        if t.name == "header" and t.find("h1"):
            continue
        t.decompose()
    for el in list(root.find_all(True)):
        if el.decomposed if hasattr(el, "decomposed") else False:
            continue
        if _tokens(el) & NOISE_TOKENS:
            el.decompose()
    if h1 and h1.parent is not None:
        h1.decompose()

    body = "\n\n".join(_blocks(root))
    return {"url": url, "title": title, "date": date, "author": author, "body": body}


def extract(fetch, listing_url):
    records = []
    for url in _collect_listing(fetch, listing_url):
        rec = _parse_release(fetch, url)
        if rec:
            records.append(rec)
    records.sort(key=lambda r: r["date"] or "", reverse=True)
    return records

import json
import re
from urllib.parse import urljoin, urlparse, urldefrag

from bs4 import BeautifulSoup
from dateutil import parser as dateparser

_JUNK_CLASS = re.compile(
    r"(share|social|related|newsletter|subscribe|cookie|consent|breadcrumb|tags?$|tag-|"
    r"contact|about-us|aboutus|boilerplate|member-cta|sidebar|promo|print|pagination|"
    r"comments|author-box|back-to)", re.I)
_STOP_HEADING = re.compile(r"^\s*(about\b|contact|media contact|related|share|more news|"
                           r"latest news|tags|subscribe|newsletter)", re.I)
_ISO_DATE = re.compile(r"(\d{4})-(\d{2})-(\d{2})")


def _soup(html):
    return BeautifulSoup(html, "html.parser")


def _clean(text):
    return re.sub(r"\s+", " ", text or "").strip()


def _norm_url(u):
    return urldefrag(u)[0]


# ---------------------------------------------------------------- listing

def _is_next_link(a):
    rel = a.get("rel") or []
    if isinstance(rel, str):
        rel = rel.split()
    if "next" in [r.lower() for r in rel]:
        return True
    txt = _clean(a.get_text()).lower()
    label = (a.get("aria-label") or "").lower()
    return txt in ("next", "next page", "older", "older posts", "›", "»", "next »", "next ›") \
        or label in ("next", "next page")


def _page_links(soup, page_url, listing_url):
    """Links to further listing pages (next / numbered pagination)."""
    out = []
    base_path = urlparse(listing_url).path.rstrip("/")
    for a in soup.find_all(["a", "link"], href=True):
        href = _norm_url(urljoin(page_url, a["href"]))
        p = urlparse(href)
        if p.netloc != urlparse(listing_url).netloc:
            continue
        if a.name == "link":
            rel = a.get("rel") or []
            if "next" in rel:
                out.append(href)
            continue
        numbered = (
            (p.path.rstrip("/") == base_path and re.search(r"(^|&)(page|p|paged)=\d+", p.query))
            or re.fullmatch(re.escape(base_path) + r"/(page/)?\d+", p.path.rstrip("/"))
        )
        if _is_next_link(a) or numbered:
            out.append(href)
    return out


def _listing_items(soup, page_url, listing_url):
    items = []
    base_path = urlparse(listing_url).path.rstrip("/")
    netloc = urlparse(listing_url).netloc

    containers = soup.select('[itemtype*="NewsArticle"], .media-item')
    anchors = []
    for c in containers:
        a = c.find("a", attrs={"itemprop": "url"}, href=True) or c.find("a", href=True)
        if a:
            anchors.append(a)
    if not anchors:
        main = soup.find("main") or soup
        for a in main.find_all("a", href=True):
            p = urlparse(urljoin(page_url, a["href"]))
            path = p.path.rstrip("/")
            if p.netloc == netloc and path.startswith(base_path + "/") and path != base_path \
                    and not re.fullmatch(re.escape(base_path) + r"/(page/)?\d+", path) \
                    and not p.query:
                anchors.append(a)
    for a in anchors:
        href = _norm_url(urljoin(page_url, a["href"]))
        if href not in items:
            items.append(href)
    return items


