            date_text = date_div.get_text(strip=True) if date_div else ""
            # Extract "Date: 18/09/2026" -> "18/09/2026"
            match = None
            if date_text.startswith("Date:"):
                date_str = date_text.split(":", 1)[1].strip()
            else:
                date_str = date_text.strip()

