                for p in main.find_all("p"):
                    txt = p.get_text(separator="\n", strip=True)
                    if txt and "lede-author" not in p.get("class", []) and "share" not in p.get("class", []):
                        paras.append(txt)
                body = "\n".join(paras) if paras else ""

        # Always include the record; do NOT filter by date <= today
        records.append({
            "url": abs_url,
            "title": title,
            "date": date_str,
            "author": author,
            "body": body
        })

    # Sort newest first by date descending
    def get_sort_key(rec):
        date_str = rec.get("date")
        if not date_str:
            return datetime.min.date()
        try:
            pub_date = parser.parse(date_str).date()
            return pub_date
        except Exception:
            return datetime.min.date()

