        if isinstance(d, str) and len(d) == 10 and d[4] == '-':
            try:
                return parser.parse(d, fuzzy=False).date()
            except Exception:
                return None
        return None

    records.sort(key=lambda r: get_date_key(r) or (0,0,0), reverse=True)

    return records

