                    for elem in main.find_all(["p", "div"], recursive=False):
                        txt = elem.get_text(separator="\n", strip=True)
                        if txt:
                            paras.append(txt)
                    body_text = "\n\n".join(paras)

            # Validate date format
            date_final = None
            if date_str:
                try:
                    datetime.strptime(date_str, "%Y-%m-%d")
                    date_final = date_str
                except ValueError:
                    pass
            if date_final is None and date_str:
                # fallback parsing from parts
                if year and month and day:
                    date_final = f"{year:04d}-{month:02d}-{day:02d}"
                    try:
                        datetime.strptime(date_final, "%Y-%m-%d")
                    except ValueError:
                        pass

            record = {
                "url": abs_url,
                "title": title if title else "",
                "date": date_final if date_final else None,
