                "body": body_text if body_text else "",
            }
            records.append(record)

    # Sort newest first by date descending
    def sort_key(r):
        if r["date"] and isinstance(r["date"], str):
            try:
                return datetime.strptime(r["date"], "%Y-%m-%d")
            except Exception:
                return datetime.min
        return datetime.min

    records.sort(key=sort_key, reverse=True)
    return records

